// Exact failed AR20 pose only. Synthetic mode certifies algebra, not Stokes physics.
#include "slurry_scattering_provider.h"
#include "slurry_spd_coordinates.h"
#include <Eigen/Eigenvalues>
#include <fstream>
#include <sstream>
#include <iostream>
#include <iomanip>
#include <cstdlib>
#include <cctype>
namespace sc=SlurryScattering;
using M12=Eigen::Matrix<double,12,12>;
using V17=Eigen::Matrix<double,17,1>;
using M5=Eigen::Matrix<double,5,5>;
using P11=Eigen::Matrix<double,11,17>;
constexpr double ar=20.,ti=.0049245303592113559,tj=.041010932014513654,az=1.7016960206944713;
std::string file(const std::string& path){std::ifstream f(path);if(!f)throw std::runtime_error("Cannot open "+path);std::ostringstream s;s<<f.rdbuf();return s.str();}
double scalar_json(const std::string& s,const std::string& key){auto at=s.find('"'+key+'"');if(at==std::string::npos)throw std::runtime_error("Missing "+key);at=s.find(':',at);char* end=nullptr;const double value=std::strtod(s.c_str()+at+1,&end);if(end==s.c_str()+at+1||!std::isfinite(value))throw std::runtime_error("Invalid "+key);return value;}
sc::Mat17 matrix_json(const std::string& s,const std::string& key){auto at=s.find('"'+key+'"');if(at==std::string::npos)throw std::runtime_error("Missing "+key);at=s.find('[',at);if(at==std::string::npos)throw std::runtime_error("Missing numeric array");const char* p=s.c_str()+at;sc::Mat17 m;for(int k=0;k<289;++k){while(*p&&(*p=='['||*p==']'||*p==','||std::isspace(static_cast<unsigned char>(*p))))++p;char* end=nullptr;m(k/17,k%17)=std::strtod(p,&end);if(end==p||!std::isfinite(m(k/17,k%17)))throw std::runtime_error("Invalid "+key);p=end;}return m;}
double rel(const Eigen::MatrixXd& a,const Eigen::MatrixXd& b){return (a-b).norm()/std::max(b.norm(),1e-300);}
template<int N>double energy(const Eigen::Matrix<double,N,N>& a,const Eigen::Matrix<double,N,N>& b){Eigen::LLT<Eigen::Matrix<double,N,N>> aa(a),bb(b);if(aa.info()!=Eigen::Success||bb.info()!=Eigen::Success)throw std::runtime_error("Energy comparison requires SPD matrices, no clipping");Eigen::GeneralizedSelfAdjointEigenSolver<Eigen::Matrix<double,N,N>> e(a,b);if(e.info()!=Eigen::Success)throw std::runtime_error("Eigensolve failed");return (e.eigenvalues().array()-1.).abs().maxCoeff();}
M5 free17(const sc::Mat17& g){return g.bottomRightCorner<5,5>()-g.bottomLeftCorner<5,12>()*g.topLeftCorner<12,12>().llt().solve(g.topRightCorner<12,5>());}
M5 free11(const sc::Mat11& h){return h.bottomRightCorner<5,5>()-h.bottomLeftCorner<5,6>()*h.topLeftCorner<6,6>().llt().solve(h.topRightCorner<6,5>());}
sc::Mat3 tensor(const Eigen::Matrix<double,5,1>& v){sc::Mat3 t=sc::Mat3::Zero();const auto es=sc::strain_basis();for(int k=0;k<5;++k)t+=v[k]*es[k];return t;}
void metric(const std::string& key,double v){if(!std::isfinite(v))throw std::runtime_error("Nonfinite "+key);std::cout<<"  \""<<key<<"\": "<<v<<",\n";}
int main(int argc,char**argv){try{
 std::string json,path,provider_path;bool synthetic=false;double h=.5;
 for(int k=1;k<argc;++k){std::string s=argv[k];if(s=="--synthetic")synthetic=true;else if((s=="--reference-json"||s=="--matrix"||s=="--provider"||s=="--h")&&k+1<argc){std::string v=argv[++k];if(s=="--reference-json")json=v;else if(s=="--matrix")path=v;else if(s=="--provider")provider_path=v;else h=std::stod(v);}else throw std::runtime_error("Usage: --synthetic | --reference-json json | --matrix txt; --h effective_gap_over_c; optional --provider bundle");}
 if(int(synthetic)+int(!json.empty())+int(!path.empty())!=1||!(h>0))throw std::runtime_error("Choose one input and positive gap");
 const std::array<sc::Vec3,2> axes{{{std::sin(ti),0.,std::cos(ti)},{std::sin(tj)*std::cos(az),std::sin(tj)*std::sin(az),std::cos(tj)}}};
 const auto bodies=sc::geometry(axes,h,ar);const auto b=sc::midpoint_map(bodies,h,ar);P11 p=P11::Zero();p.topLeftCorner<6,12>()=b;p.bottomRightCorner<5,5>().setIdentity();
 sc::Provider self;self.basis.aspect_ratio=ar;self.isolated_local=SlurrySPDCoordinates::Shape(ar).isolated_local;const sc::Mat17 g0=self.isolated(bodies);sc::Mat17 raw;double self_error=0;
 if(synthetic){Eigen::Matrix<double,17,5> v;for(int i=0;i<17;++i)for(int j=0;j<5;++j)v(i,j)=std::sqrt(g0(i,i))*std::sin(.71*(i+1)*(j+1))/std::sqrt(17.);raw=g0+.7*v*v.transpose();}
 else if(!json.empty()){const auto s=file(json);if(std::abs(scalar_json(s,"aspect_ratio")-ar)>1e-12||std::abs(scalar_json(s,"h_over_c")-h)>1e-13||std::abs(scalar_json(s,"theta_i")-ti)>1e-14||std::abs(scalar_json(s,"theta_j")-tj)>1e-14||std::abs(scalar_json(s,"phi")-az)>1e-14)throw std::runtime_error("Reference metadata does not match the exact AR20 failed pose and requested gap");raw=matrix_json(s,"raw_full17");if(s.find("\"isolated_full17\"")!=std::string::npos)self_error=rel(matrix_json(s,"isolated_full17"),g0);}
 else{std::ifstream f(path);for(int i=0;i<17;++i)for(int j=0;j<17;++j)if(!(f>>raw(i,j)))throw std::runtime_error("Expected289row-major matrix numbers");}
 const sc::Mat17 g=.5*(raw+raw.transpose()).eval();Eigen::LLT<sc::Mat17> check(g);if(check.info()!=Eigen::Success)throw std::runtime_error("Full17 not SPD; no clipping");
 const sc::Mat11 reduced=sc::reduced(g,b),h0=sc::reduced(g0,b);const sc::Mat17 lift=g0+p.transpose()*(reduced-h0)*p;
 const M12 a=g.topLeftCorner<12,12>();const Eigen::Matrix<double,12,5> c=g.topRightCorner<12,5>();
 const double ascale=a.cwiseAbs().maxCoeff();Eigen::Matrix<double,18,18> saddle=Eigen::Matrix<double,18,18>::Zero();saddle.topLeftCorner<12,12>()=a/ascale;saddle.topRightCorner<12,6>()=b.transpose();saddle.bottomLeftCorner<6,12>()=b;Eigen::FullPivLU<Eigen::Matrix<double,18,18>> lu(saddle);if(!lu.isInvertible())throw std::runtime_error("Singular KKT matrix");
 double constraint=0,conditional_energy=0,conditional_force=0,conditional_stress=0;
 for(int k=0;k<11;++k){const Eigen::Matrix<double,11,1> y=Eigen::Matrix<double,11,1>::Unit(k);Eigen::Matrix<double,18,1> rhs=Eigen::Matrix<double,18,1>::Zero();rhs.head<12>()=-c*y.tail<5>()/ascale;rhs.tail<6>()=y.head<6>();const auto solution=lu.solve(rhs).eval();V17 z;z.head<12>()=solution.head<12>();z.tail<5>()=y.tail<5>();const V17 response=g*z,projected=p.transpose()*reduced*y;constraint=std::max(constraint,(b*z.head<12>()-y.head<6>()).norm());conditional_energy=std::max(conditional_energy,std::abs(z.dot(g*z)-y.dot(reduced*y))/std::max(std::abs(y.dot(reduced*y)),1e-300));conditional_force=std::max(conditional_force,(response.head<12>()-projected.head<12>()).norm()/std::max(response.norm(),1e-300));conditional_stress=std::max(conditional_stress,(response.tail<5>()-projected.tail<5>()).norm()/std::max(response.norm(),1e-300));}
 const sc::Vec3 middle(0.,0.,h/2);Eigen::Matrix<double,17,6> common=Eigen::Matrix<double,17,6>::Zero();for(int k=0;k<3;++k)for(int i=0;i<2;++i){common.block<3,1>(6*i,k)=sc::Vec3::Unit(k);common.block<3,1>(6*i,k+3)=sc::Vec3::Unit(k).cross(bodies[i].center-middle)/ar;common.block<3,1>(6*i+3,k+3)=sc::Vec3::Unit(k);}
 Eigen::Matrix<double,17,5> fixed=Eigen::Matrix<double,17,5>::Zero();fixed.bottomRows<5>().setIdentity();const auto es=sc::strain_basis();for(int k=0;k<5;++k)for(int i=0;i<2;++i)fixed.block<3,1>(6*i,k)=-es[k]*(bodies[i].center-middle)/ar;
 const Eigen::Matrix<double,17,5> held=g*fixed;const M5 held_matrix=fixed.transpose()*g*fixed,held_lift=fixed.transpose()*lift*fixed;double chain=0,fd_error=0;const double step=1e-5;
 for(int k=0;k<5;++k){const V17 r=held.col(k);sc::Mat3 origin=tensor(ar*r.tail<5>());for(int i=0;i<2;++i){const sc::Vec3 loc=bodies[i].center-middle,f=r.segment<3>(6*i);origin-=.5*(loc*f.transpose()+f*loc.transpose());}origin-=origin.trace()/3.*sc::Mat3::Identity();const sc::Mat3 expected=tensor(ar*held_matrix.col(k));chain=std::max(chain,(origin-expected).norm()/std::max(expected.norm(),1e-300));for(int j=0;j<5;++j){Eigen::Matrix<double,5,1> plus=Eigen::Matrix<double,5,1>::Unit(k),minus=plus;plus[j]+=step;minus[j]-=step;const V17 zp=fixed*plus,zm=fixed*minus;const double fd=(zp.dot(g*zp)-zm.dot(g*zm))/(4*step);fd_error=std::max(fd_error,std::abs(fd-held_matrix(j,k))/std::max(held_matrix.norm(),1e-300));}}
 const Eigen::Matrix<double,12,5> fv=-a.llt().solve(c),fl=-lift.topLeftCorner<12,12>().llt().solve(lift.topRightCorner<12,5>());const sc::Mat17 delta=lift-g;
 Eigen::Matrix<double,6,17> rf,df,rt,dt;rf<<g.block<3,17>(0,0),g.block<3,17>(6,0);df<<delta.block<3,17>(0,0),delta.block<3,17>(6,0);rt<<g.block<3,17>(3,0),g.block<3,17>(9,0);dt<<delta.block<3,17>(3,0),delta.block<3,17>(9,0);
 std::cout<<std::setprecision(17)<<"{\n  \"method\": \"ar20_failed_pose_reduction_audit\",\n  \"reference_kind\": \""<<(synthetic?"manufactured_spd_algebra_only":"supplied_full17_not_certified_by_this_probe")<<"\",\n  \"scope\": \"One failed AR20 pose; no Stokes convergence or table interpolation certification\",\n  \"units\": \"c=eta=1; input U-uinf,a(Omega-Omegainf),aE; output Ffluid,Tfluid/a,intrinsicS/a\",\n  \"fixed_body_strain\": \"Ui=Omegai=0; uinf=E(x-midpoint), Omegainf=0; first12 NOT zero\",\n";
 metric("ar",ar);metric("theta_i",ti);metric("theta_j",tj);metric("phi",az);metric("effective_gap_over_c",h);metric("raw_reciprocity",(raw-raw.transpose()).norm()/raw.norm());metric("supplied_self_relative_error",self_error);metric("conditional_constraint_error",constraint);metric("conditional_energy_relative_error",conditional_energy);metric("conditional_force_torque_scaled_error",conditional_force);metric("conditional_intrinsic_stress_scaled_error",conditional_stress);metric("relift_reduction_energy_error",energy<11>(sc::reduced(lift,b),reduced));
 metric("full17_runtime_worst_relative_energy_error",energy<17>(lift,g));metric("prescribed_force_relative_frobenius_error",df.norm()/rf.norm());metric("prescribed_torque_over_a_relative_frobenius_error",dt.norm()/rt.norm());metric("prescribed_intrinsic_stress_over_a_relative_frobenius_error",delta.bottomRows<5>().norm()/g.bottomRows<5>().norm());metric("common_projection_null_error",(p*common).norm());metric("common_motion_pair_correction_scaled_norm",((lift-g0)*common).norm()/g0.norm());metric("common_motion_full_response_relative_error",rel(lift*common,g*common));metric("free_strain_schur_reduction_error",rel(free11(reduced),free17(g)));metric("free_strain_runtime_stress_error",rel(free17(lift),free17(g)));metric("free_strain_runtime_velocity_error",rel(fl,fv));metric("fixed_body_origin_dipole_worst_energy_error",energy<5>(held_lift,held_matrix));metric("fixed_body_intrinsic_stress_error",rel((lift*fixed).bottomRows<5>(),held.bottomRows<5>()));metric("fixed_body_stress_chain_rule_error",chain);metric("fixed_body_energy_derivative_error",fd_error);
 if(!provider_path.empty()){sc::Provider provider;provider.load(provider_path);if(provider.basis.aspect_ratio!=ar)throw std::runtime_error("Provider must be AR20");const sc::Mat11 correction=provider.correction(axes,h,0.);const sc::Mat17 candidate=g0+p.transpose()*correction*p;metric("provider_total11_worst_energy_error",energy<11>(h0+correction,reduced));metric("provider_full17_worst_energy_error",energy<17>(candidate,g));metric("provider_intrinsic_stress_operator_error",rel(candidate.bottomRows<5>(),g.bottomRows<5>()));}
 const bool pass=constraint<1e-10&&conditional_energy<1e-10&&conditional_force<1e-10&&conditional_stress<1e-10&&chain<1e-10&&fd_error<1e-7&&self_error<1e-10;std::cout<<"  \"algebra_gate_passed\": "<<(pass?"true":"false")<<",\n  \"physical_accuracy_qualified\": false\n}\n";return pass?0:2;
 }catch(const std::exception& e){std::cerr<<"AR20 reduction audit: "<<e.what()<<'\n';return 1;}}
